def coin_change(coins, amount):
    def f(i, a):               # fewest of the first i coin types making a
        if a == 0:
            return 0
        if i == 0:
            return inf
        best = f(i - 1, a)
        c = coins[i - 1]
        if c <= a:
            best = min(best, 1 + f(i, a - c))
        return best
    ans = f(len(coins), amount)
    return ans if ans != inf else -1

